import cv2,glob,numpy as np,os
cas=cv2.CascadeClassifier(cv2.data.haarcascades+'haarcascade_frontalface_alt2.xml')
def feat(p):
 im=cv2.imread(p,0); fs=cas.detectMultiScale(im,1.06,4,minSize=(35,35));
 if len(fs): x,y,w,h=max(fs,key=lambda z:z[2]*z[3]); im=im[y:y+h,x:x+w]
 im=cv2.resize(im,(128,128)); im=cv2.equalizeHist(im); c=im[1:-1,1:-1]; l=np.zeros_like(c)
 ns=[im[:-2,:-2],im[:-2,1:-1],im[:-2,2:],im[1:-1,2:],im[2:,2:],im[2:,1:-1],im[2:,:-2],im[1:-1,:-2]]
 for b,n in enumerate(ns): l|=((n>=c)<<b).astype('uint8')
 out=[]
 for row in np.array_split(l,12,0):
  for cell in np.array_split(row,12,1):
   h=np.bincount(cell.ravel(),minlength=256).astype(float); h/=h.sum();out.extend(h)
 return np.array(out)
ps=sorted(glob.glob('/workspace/materials/roster/*.jpg')); X=np.array([feat(p) for p in ps]); q=feat('/home/agent/.copilot/session-state/bfb4a19f-a739-4875-b065-135ef02ab6ed/files/turn_faces/turn_56.jpg')
# chi-square
ds=.5*np.sum((X-q)**2/(X+q+1e-9),axis=1);o=np.argsort(ds)
print('rank301',np.where(o==300)[0][0]+1)
print([(os.path.basename(ps[i])[8:11],round(ds[i],2)) for i in o[:30]])
